import{_ as o,o as a,c as n,a2 as e}from"./chunks/framework.A5mep7Fe.js";const g=JSON.parse('{"title":"🧩 03 · 记忆系统与工具调用","description":"","frontmatter":{},"headers":[],"relativePath":"03-算法岗-AI-Agent/03-记忆系统与工具调用.md","filePath":"03-算法岗-AI-Agent/03-记忆系统与工具调用.md","lastUpdated":1786806808000}'),l={name:"03-算法岗-AI-Agent/03-记忆系统与工具调用.md"};function s(r,t,i,u,p,c){return a(),n("div",null,[...t[0]||(t[0]=[e(`<h1 id="🧩-03-·-记忆系统与工具调用" tabindex="-1">🧩 03 · 记忆系统与工具调用 <a class="header-anchor" href="#🧩-03-·-记忆系统与工具调用" aria-label="Permalink to &quot;🧩 03 · 记忆系统与工具调用&quot;">​</a></h1><blockquote><p>Agent 的「记忆」让它跨轮次连贯，「工具」让它真正动手。两个能力决定 Agent 是玩具还是生产力。</p></blockquote><hr><h2 id="一、记忆系统-memory" tabindex="-1">一、记忆系统（Memory） <a class="header-anchor" href="#一、记忆系统-memory" aria-label="Permalink to &quot;一、记忆系统（Memory）&quot;">​</a></h2><h3 id="短期记忆-short-term" tabindex="-1">短期记忆（Short-term） <a class="header-anchor" href="#短期记忆-short-term" aria-label="Permalink to &quot;短期记忆（Short-term）&quot;">​</a></h3><ul><li>当前对话上下文（prompt 窗口内）</li><li>实现：滑动窗口、最近 N 轮</li><li>瓶颈：上下文长度有限、长对话会丢信息</li></ul><h3 id="长期记忆-long-term" tabindex="-1">长期记忆（Long-term） <a class="header-anchor" href="#长期记忆-long-term" aria-label="Permalink to &quot;长期记忆（Long-term）&quot;">​</a></h3><ul><li>跨会话持久化知识</li><li>实现： <ul><li><strong>向量库</strong>（语义检索历史）</li><li><strong>摘要压缩</strong>（定期把旧对话摘要，腾出空间）</li><li><strong>结构化存储</strong>（数据库/知识库，按 key 检索）</li></ul></li></ul><h3 id="记忆管理策略" tabindex="-1">记忆管理策略 <a class="header-anchor" href="#记忆管理策略" aria-label="Permalink to &quot;记忆管理策略&quot;">​</a></h3><ul><li><strong>写入</strong>：重要结论/用户偏好显式存入长期记忆</li><li><strong>检索</strong>：按需从长期记忆拉取相关片段</li><li><strong>压缩</strong>：超长对话做摘要，保留关键信息</li></ul><hr><h2 id="二、工具调用-tool-use-function-calling-⭐" tabindex="-1">二、工具调用（Tool Use / Function Calling）⭐ <a class="header-anchor" href="#二、工具调用-tool-use-function-calling-⭐" aria-label="Permalink to &quot;二、工具调用（Tool Use / Function Calling）⭐&quot;">​</a></h2><p><strong>Function Calling</strong>：用 JSON Schema 定义函数，LLM 输出「调用哪个函数 + 参数」，由外部执行并返回结果。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>tools = [{</span></span>
<span class="line"><span>  &quot;name&quot;: &quot;get_weather&quot;,</span></span>
<span class="line"><span>  &quot;description&quot;: &quot;查询天气&quot;,</span></span>
<span class="line"><span>  &quot;parameters&quot;: {&quot;type&quot;:&quot;object&quot;,&quot;properties&quot;:{&quot;city&quot;:{&quot;type&quot;:&quot;string&quot;}}}</span></span>
<span class="line"><span>}]</span></span>
<span class="line"><span># 模型输出：{&quot;name&quot;:&quot;get_weather&quot;,&quot;arguments&quot;:{&quot;city&quot;:&quot;北京&quot;}}</span></span>
<span class="line"><span># 执行后把结果回灌给模型继续推理</span></span></code></pre></div><p><strong>Tool Use vs Function Calling</strong>：</p><ul><li>Function Calling：标准化（JSON Schema）、易实现、兼容 OpenAI API</li><li>Tool Use：更灵活的工具描述、可并行调用多个工具、元数据更丰富</li><li>选择：简单场景 Function Calling；复杂工具系统/需并行 → Tool Use</li></ul><hr><h2 id="三、工具路由与安全-⭐-生产必问" tabindex="-1">三、工具路由与安全（⭐ 生产必问） <a class="header-anchor" href="#三、工具路由与安全-⭐-生产必问" aria-label="Permalink to &quot;三、工具路由与安全（⭐ 生产必问）&quot;">​</a></h2><ul><li><strong>工具路由</strong>：多个工具时，如何选对工具？靠工具描述质量 + few-shot + 必要时用「分类器/检索」先筛工具。</li><li><strong>参数校验</strong>：模型给的参数不可信，必须做 schema 校验、类型转换、边界检查。</li><li><strong>安全</strong>： <ul><li>危险操作（删库、发邮件）需<strong>人工确认/权限控制</strong></li><li>工具输出可能含注入（提示注入攻击），需隔离/清洗</li><li>限制工具执行超时、资源、次数</li></ul></li></ul><hr><h2 id="四、高频追问" tabindex="-1">四、高频追问 <a class="header-anchor" href="#四、高频追问" aria-label="Permalink to &quot;四、高频追问&quot;">​</a></h2><p><strong>Q1：如何优化 Agent 的工具选择准确性？</strong></p><blockquote><p>清晰工具名/描述/参数示例、few-shot、按需检索缩小候选工具集、错误后反馈学习、必要时用小模型做工具路由分类。</p></blockquote><p><strong>Q2：短期记忆不够怎么办？</strong></p><blockquote><p>滑动窗口 + 摘要压缩 + 长期记忆检索；把关键事实显式提取存库，对话中按需拉取，而非全量塞上下文。</p></blockquote><p><strong>Q3：怎么防御提示注入（Prompt Injection）？</strong></p><blockquote><p>把工具返回内容当「不可信数据」隔离、不执行其中的指令、输出做清洗、高危工具加权限与人工确认、最小权限原则。</p></blockquote><p><strong>Q4：工具调用失败怎么处理？</strong></p><blockquote><p>重试 + 错误回灌给模型让其自我修正、备用工具、超时/资源限制、无法恢复时优雅降级并如实告知用户。</p></blockquote><hr><p>➡️ 下一步：<a href="./04-MCP与多Agent">04-MCP与多Agent</a></p>`,31)])])}const q=o(l,[["render",s]]);export{g as __pageData,q as default};
